// Small rule drawing (generated by tools/gen_swatches.py into static/img/swatches). Click it to show the rules it draws
// (the generated <name>.json, so the text always matches the picture) in a floating panel: the table keeps its shape.
// Carries .pm-graphic so the navbar graphics switch hides it.
import React, {useEffect, useRef, useState} from 'react';
import ThemedImage from '@theme/ThemedImage';
import useBaseUrl from '@docusaurus/useBaseUrl';

export default function Swatch({name}) {
  const [json, setJson] = useState(null);
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  const light = useBaseUrl(`/img/swatches/${name}.svg`);
  const dark = useBaseUrl(`/img/swatches/${name}-dark.svg`);
  const src = useBaseUrl(`/img/swatches/${name}.json`);
  useEffect(() => {
    if (!open) return undefined;
    if (json === null) fetch(src).then((r) => (r.ok ? r.text() : '')).then(setJson).catch(() => setJson(''));
    const close = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const esc = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('mousedown', close);
    document.addEventListener('keydown', esc);
    return () => { document.removeEventListener('mousedown', close); document.removeEventListener('keydown', esc); };
  }, [open]);
  return (
    <span ref={ref} className="pm-graphic pm-swatch">
      <button type="button" className="clean-btn pm-swatch-btn" title="Show the rule's JSON" aria-expanded={open}
              onClick={() => setOpen(!open)}>
        <ThemedImage alt={name.replace(/[-_]/g, ' ')} width={120} sources={{light, dark}}/>
      </button>
      {open && <pre className="pm-swatch-json">{json === null ? '…' : json}</pre>}
    </span>
  );
}
